fn encode_cyclic(s: Vec<i8>) -> Vec<i8> {
    let mut result = Vec::with_capacity(s.len());
    for chunk in s.chunks(3) {
        match chunk {
            [a, b, c] => {
                // shift [a, b, c] to [b, c, a]
                result.push(*b);
                result.push(*c);
                result.push(*a);
            }
            // for remaining 1 or 2 elements, leave them unchanged
            _ => result.extend_from_slice(chunk),
        }
    }
    result
}

